/**
 * uid/device_id 字符串 -> 聚合成一个 SR 兼容 bitmap; NULL 跳过(对齐 TO_BITMAP(NULL))。
 * 中间态用 BINARY 而非 Kryo(Roaring64NavigableMap)：prod 大分区上 Kryo buffer 会 overflow。
 * ⚠️ BINARY 每行 deser+ser 整个 bitmap，大分区可能比 Kryo 慢 —— 上产前须在测试集群对比
 *    （见 bm_union_kryo / bm_union_binary 与 sql/probe_bitmap_binary_vs_kryo.sql）。
 */
class BmUnionAgg extends Aggregator[String, Array[Byte], Array[Byte]] {
  def zero: Array[Byte] = BM.empty()
  def reduce(buf: Array[Byte], s: String): Array[Byte] = {
    if (s != null && s.trim.nonEmpty) {
      val x = BM.deser(buf); x.addLong(BM.hash(s)); BM.ser(x)
    } else buf
  }
  def merge(b1: Array[Byte], b2: Array[Byte]): Array[Byte] = BM.or(b1, b2)
  def finish(b: Array[Byte]): Array[Byte] = if (b == null) BM.empty() else b
  def bufferEncoder: Encoder[Array[Byte]] = Encoders.BINARY
  def outputEncoder: Encoder[Array[Byte]] = Encoders.BINARY
}

/** 已序列化的 bitmap 再做并集 —— 留存侧读活跃表时用；中间态同 BmUnionAgg 走 BINARY */
class BmMergeAgg extends Aggregator[Array[Byte], Array[Byte], Array[Byte]] {
  def zero: Array[Byte] = BM.empty()
  def reduce(buf: Array[Byte], b: Array[Byte]): Array[Byte] = {
    if (b != null && b.length > 0) BM.or(buf, b) else buf
  }
  def merge(b1: Array[Byte], b2: Array[Byte]): Array[Byte] = BM.or(b1, b2)
  def finish(b: Array[Byte]): Array[Byte] = if (b == null) BM.empty() else b
  def bufferEncoder: Encoder[Array[Byte]] = Encoders.BINARY
  def outputEncoder: Encoder[Array[Byte]] = Encoders.BINARY
}

/** 旧实现：中间态 Kryo(Roaring64NavigableMap)。大分区可能 Kryo buffer overflow；对照测用 bm_union_kryo。 */
class BmUnionAggKryo extends Aggregator[String, Roaring64NavigableMap, Array[Byte]] {
  def zero: Roaring64NavigableMap = new Roaring64NavigableMap()
  def reduce(buf: Roaring64NavigableMap, s: String): Roaring64NavigableMap = {
    if (s != null && s.trim.nonEmpty) buf.addLong(BM.hash(s))
    buf
  }
  def merge(b1: Roaring64NavigableMap, b2: Roaring64NavigableMap): Roaring64NavigableMap = { b1.or(b2); b1 }
  def finish(b: Roaring64NavigableMap): Array[Byte] = BM.ser(b)
  def bufferEncoder: Encoder[Roaring64NavigableMap] = Encoders.kryo[Roaring64NavigableMap]
  def outputEncoder: Encoder[Array[Byte]] = Encoders.BINARY
}

class BmMergeAggKryo extends Aggregator[Array[Byte], Roaring64NavigableMap, Array[Byte]] {
  def zero: Roaring64NavigableMap = new Roaring64NavigableMap()
  def reduce(buf: Roaring64NavigableMap, b: Array[Byte]): Roaring64NavigableMap = {
    if (b != null && b.length > 0) buf.or(BM.deser(b))
    buf
  }
  def merge(b1: Roaring64NavigableMap, b2: Roaring64NavigableMap): Roaring64NavigableMap = { b1.or(b2); b1 }
  def finish(b: Roaring64NavigableMap): Array[Byte] = BM.ser(b)
  def bufferEncoder: Encoder[Roaring64NavigableMap] = Encoders.kryo[Roaring64NavigableMap]
  def outputEncoder: Encoder[Array[Byte]] = Encoders.BINARY
}

object BitmapUdf {
  private val log = LoggerFactory.getLogger(getClass)

  /** 幂等: 重复注册同名函数只是覆盖, 不报错 */
  def register(spark: SparkSession): Unit = {
    spark.udf.register("bm_union", udaf(new BmUnionAgg))
    spark.udf.register("bm_merge", udaf(new BmMergeAgg))
    // A/B 对照名（与上同实现 / Kryo 旧实现），probe_bitmap_binary_vs_kryo 用
    spark.udf.register("bm_union_binary", udaf(new BmUnionAgg))
    spark.udf.register("bm_merge_binary", udaf(new BmMergeAgg))
    spark.udf.register("bm_union_kryo", udaf(new BmUnionAggKryo))
    spark.udf.register("bm_merge_kryo", udaf(new BmMergeAggKryo))
    spark.udf.register("bm_and",   (a: Array[Byte], b: Array[Byte]) => BM.and(a, b))
    spark.udf.register("bm_or",    (a: Array[Byte], b: Array[Byte]) => BM.or(a, b))
    spark.udf.register("bm_andnot",(a: Array[Byte], b: Array[Byte]) => BM.andnot(a, b))
    spark.udf.register("bm_count", (a: Array[Byte]) => BM.count(a))
    spark.udf.register("bm_empty", () => BM.empty())
    spark.udf.register("bm_hex",   (a: Array[Byte]) => BM.hex(a))
    log.info("[bm_udf] registered: bm_union bm_merge bm_union_binary bm_union_kryo bm_and bm_or bm_andnot bm_count bm_empty bm_hex")
  }
